    QTest::addColumn<bool>("useTabs");
    QTest::addColumn<int>("expectedShells");
    QTest::addColumn<int>("expectedTabs");

    QTest::newRow("new-window") << false << 2 << 2;
    QTest::newRow("new-tab") << true << 1 << 2;
